steps.script:
# ai_hidden_awareness_11e's board: every OTHER unit parked in the far corner,
# the Shield-Captain in the dense area at (260,750), the Battlewagon 10" away
# as its only legal target (a chip shot into a T12 hull).
for uid in GameState.state["units"]:
	if uid == "U_SHIELD_CAPTAIN_A" or uid == "U_BATTLEWAGON_G":
		continue
	var u = GameState.state["units"][uid]
	var k = 0
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		m["position"] = {"x": 1650.0 + float(k % 5) * 45.0, "y": 1980.0 + float(k / 5) * 45.0}
		k += 1
var sc = GameState.state["units"]["U_SHIELD_CAPTAIN_A"]
for m in sc["models"]:
	m["position"] = {"x": 260.0, "y": 750.0}
sc["flags"] = {}
var bw = GameState.state["units"]["U_BATTLEWAGON_G"]
for m in bw["models"]:
	m["position"] = {"x": 260.0, "y": 1150.0}
# Battle round 2, Player 1 first: Player 1's turn is play-order index 4.
GameState.state["meta"]["first_turn_player"] = 1
GameState.state["meta"]["battle_round"] = 2
GameState.state["meta"]["active_player"] = 1
# The shot record a FIRE OVERWATCH writes in Player 2's battle-round-1 turn
# (index 3): the engine's own writer, HiddenShotRecord.stamp_diffs, applied
# with the turn counter at that turn.
var HSR = load("res://scripts/rules/HiddenShotRecord.gd")
GameState.state["meta"]["battle_round"] = 1
GameState.state["meta"]["active_player"] = 2
PhaseManager.apply_state_changes(HSR.stamp_diffs("U_SHIELD_CAPTAIN_A"))
GameState.state["meta"]["battle_round"] = 2
GameState.state["meta"]["active_player"] = 1
return int(sc["flags"].get("last_shot_idx", -1)) == 3 and int(GameState.get_player_turn_index()) == 4

# The Hidden weights ship OFF (neutral): load the profile that turns them on.
var f = FileAccess.open("res://tests/bench_profiles/yt_findings_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
AIDecisionMaker._current_player = 1
return int(prof["parameters"].size())

# ENGINE: the overwatch in the opponent's last turn still counts this turn.
var tm = tree.root.get_node_or_null("TerrainManager")
var u = GameState.state["units"]["U_SHIELD_CAPTAIN_A"]
for m in u["models"]:
	if m.get("alive", true) and tm.is_model_hidden(m, u):
		return "hidden now"
return "not hidden now"

# ENGINE: ... and no longer counts in the enemy's next turn (index 5).
var tm = tree.root.get_node_or_null("TerrainManager")
var u = GameState.state["units"]["U_SHIELD_CAPTAIN_A"]
var n = 0
for m in u["models"]:
	if m.get("alive", true) and tm.is_model_hidden_at(m, u, int(GameState.get_player_turn_index()) + 1):
		n += 1
return n

var snap = GameState.create_snapshot()
var u = snap["units"]["U_SHIELD_CAPTAIN_A"]
var enemies = AIDecisionMaker._get_shootable_enemy_units(snap, 1)
return AIDecisionMaker._hidden_forfeit_cost(u, enemies, snap)

# A real '▸ details' click on every option (the panel's own link handler,
# toggle_section), then the text the panel now shows: the hover tooltip of
# 'Cost of losing Hidden' is the corrected glossary help.
var p = tree.root.get_node_or_null("Main")._ai_suggestion_panel
var built = p.build_breakdown(p._decision, p._meta, {}, true)
var rx = RegEx.new()
rx.compile("\\[url=(opt:[0-9]+:[0-9]+)\\]")
var keys = []
for m in rx.search_all(str(built.bbcode)):
	var k = m.get_string(1)
	if not k in keys:
		keys.append(k)
for k in keys:
	if not bool(p._expanded.get(k, false)):
		p.toggle_section(k)
var now = p.build_breakdown(p._decision, p._meta, p._expanded, false)
return keys.size() > 0 and str(now.bbcode).contains("hands the enemy's next turn a target")

AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var d = AIDecisionMaker.decide(8, snap, [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}], 1)
var f = FileAccess.open("user://hidden_after_overwatch.txt", FileAccess.WRITE)
f.store_line("overwatched last turn -> type=%s desc=%s" % [str(d.get("type", "?")), str(d.get("_ai_description", ""))])
f.close()
return str(d.get("_ai_description", "")).contains("holds fire to be Hidden next turn")

# CONTROL: a shot record from THIS turn (index 4) counts next turn too —
# nothing left to sell, so the same chip shot is taken.
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
snap["units"]["U_SHIELD_CAPTAIN_A"]["flags"]["last_shot_idx"] = int(GameState.get_player_turn_index())
var d = AIDecisionMaker.decide(8, snap, [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}], 1)
return str(d.get("type", "?"))

# SHIPPED-DEFAULT CHECK: the profile cleared, the same decision shoots.
AIDecisionMaker.clear_player_profile(1)
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var d = AIDecisionMaker.decide(8, snap, [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}], 1)
return str(d.get("type", "?"))
